from typing import List
from sortedcontainers import SortedList

def find_minimum_index_difference(N: int, K: int, P: List[int]) -> int:
    C = [-1 for _ in range(N)]

    for i, p in enumerate(P):
        C[p-1] = i

    ans = float('inf')

    s = SortedList(C[:K])

    for i in range(N-K+1):
        if i > 0:
            s.remove(C[i-1])
            s.add(C[i+K-1])
        if max(s) - min(s) == K-1:
            ans = min(ans, max(s) - min(s))

    return ans
